export function wrapType(
	data: T.Type & { readonly $other?: T.Type | readonly T.Type[] },
	tree: TreeHandle
): T.Type.Parsed {
	if (typeof data === 'number') return data as unknown as T.Type.Parsed;
	const node = _keepModelledSlots(data, [
		'_abstract_type',
		'_reference_type',
		'_metavariable',
		'_pointer_type',
		'_generic_type',
		'_scoped_type_identifier',
		'_tuple_type',
		'_unit_type',
		'_array_type',
		'_function_type',
		'_type_identifier',
		'_macro_invocation',
		'_never_type',
		'_dynamic_type',
		'_bounded_type',
		'_removed_trait_bound',
		'_primitive_type',
		'_identifier',
		'_pointer_type_const',
		'_pointer_type_mut'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'abstract_type',
		'reference_type',
		'metavariable',
		'pointer_type',
		'generic_type',
		'scoped_type_identifier',
		'tuple_type',
		'unit_type',
		'array_type',
		'function_type',
		'type_identifier',
		'macro_invocation',
		'never_type',
		'dynamic_type',
		'bounded_type',
		'removed_trait_bound',
		'primitive_type',
		'identifier',
		'pointer_type_const',
		'pointer_type_mut'
	]) as T.Type | readonly T.Type[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'abstract_type',
			'reference_type',
			'metavariable',
			'pointer_type',
			'generic_type',
			'scoped_type_identifier',
			'tuple_type',
			'unit_type',
			'array_type',
			'function_type',
			'type_identifier',
			'macro_invocation',
			'never_type',
			'dynamic_type',
			'bounded_type',
			'removed_trait_bound',
			'primitive_type',
			'identifier',
			'pointer_type_const',
			'pointer_type_mut'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _NodeData).$text === 'string' || (node as _NodeData).$nodeHandle != null)
	) {
		return drillInSelf<T.Type>(node as T.Type, tree) as unknown as T.Type.Parsed;
	}
	return drillIn<T.Type>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _NodeData).$span
		}),
		tree
	);
}

